/*
[演算法邏輯說明]
給定一組正整數，將其拼接成最大的整數。
1. 這是一個排序問題，但排序的規則不是傳統的數值大小，而是「拼接後的字典序」。
2. 對於兩個字串 a 和 b，我們比較 (a + b) 和 (b + a) 的大小。
   - 如果 a + b > b + a，則 a 應該排在 b 的前面。
   - 否則，b 應該排在 a 的前面。
3. 使用這種自定義的比較規則對所有數位字串進行排序。
4. 最後依序輸出排序後的字串即可。
*/

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

using namespace std;

bool compareStrings(const string& a, const string& b) {
    return (a + b) > (b + a);
}

int main() {
    int n;
    while (cin >> n && n != 0) {
        vector<string> nums(n);
        for (int i = 0; i < n; ++i) cin >> nums[i];
        sort(nums.begin(), nums.end(), compareStrings);
        for (int i = 0; i < n; ++i) cout << nums[i];
        cout << endl;
    }
    return 0;
}
